mapper.select:
select pt.PORTFOLIO_ID id, pt.PORTFOLIO_NAME text from PTL_PORTFOLIO pt INNER JOIN PTL_PORTFOLIO_AUTHORITY AUTH ON AUTH.PORTFOLIO_ID = pt.PORTFOLIO_ID
pt.PORTFOLIO_ID = #{initValue}
and (instr(pt.PORTFOLIO_ID, #{search}) > 0 or instr(pt.PORTFOLIO_NAME, #{search}) > 0)
and AUTH.USER_ID = #{userId}

		select * from (



			select

			#{PAGE_DATA_STATUS_01} pageDataStatus,


			null arrivalDate,

			null actRecPrincipa,
			null actPrincipa

			from TRD_PRODUCT_DEAL tpd

			where 

                pp.INVEST_YESORNO = 'Y' AND tpd.TRADE_STATUS = 	#{TRADE_STATUS_01}

                and tpd.IS_CANCEL = #{YES_OR_NO_N}	

                and tpd.BUSI_TYPE = #{COM_TYPE_TRD03}

				and tpd.PS in (#{PS_CR},#{PS_CC})
				and NOT EXISTS
				(
					select 1 from TRD_PRODUCT_DEAL tpd1 
					inner join TRD_PRODUCT_DEAL tpd2 on tpd1.FINPROD_ID = tpd2.FINPROD_ID
					and tpd2.PS in (#{PS_CRDQ},#{PS_CCDQ})
					and tpd2.TRADE_STATUS = 	#{TRADE_STATUS_01}
					and tpd2.IS_CANCEL = #{YES_OR_NO_N} 
				)




            union all
            select

            #{PAGE_DATA_STATUS_03} pageDataStatus,


            null arrivalDate,

            null actRecPrincipa,
            null actPrincipa

            from WFL_TRD_PRODUCT_DEAL tpd

            where 

                tpd.TRADE_STATUS =  #{TRADE_STATUS_01}



                and tpd.BUSI_TYPE = #{COM_TYPE_TRD03}

                and tpd.MDATE = #{PLATFORM_DAY}

                and tpd.PS in (#{PS_CR},#{PS_CC})




            union all
            select

            #{PAGE_DATA_STATUS_05} pageDataStatus,


            tpd1.TRADE_DATE arrivalDate,

            tpd1.TRADE_AMT actRecPrincipa,
            tpd1.TRADE_AMT actPrincipa

            from TRD_PRODUCT_DEAL tpd

            inner join TRD_PRODUCT_DEAL tpd1 on tpd.FINPROD_ID = tpd1.FINPROD_ID
	            and tpd1.PS in (#{PS_CRDQ},#{PS_CCDQ}) 
	            and tpd1.TRADE_STATUS = #{TRADE_STATUS_01}
	            and tpd1.IS_CANCEL = #{YES_OR_NO_N} 
            where 

            pp.INVEST_YESORNO = 'Y' AND tpd.TRADE_STATUS =  #{TRADE_STATUS_01}

                and tpd.IS_CANCEL = #{YES_OR_NO_N}  

                and tpd.BUSI_TYPE = #{COM_TYPE_TRD03}

                and tpd.PS in (#{PS_CR},#{PS_CC})




            union all
            select

            #{PAGE_DATA_STATUS_06} pageDataStatus,


            tpd1.TRADE_DATE arrivalDate,

            tpd1.TRADE_AMT actRecPrincipa,
            tpd1.TRADE_AMT actPrincipa

            from TRD_PRODUCT_DEAL tpd

            left join TRD_PRODUCT_DEAL tpd1 on tpd.FINPROD_ID = tpd1.FINPROD_ID
                and tpd1.PS in (#{PS_CRDQ},#{PS_CCDQ})

                and tpd1.TRADE_STATUS = #{TRADE_STATUS_03}

                and tpd1.IS_CANCEL = #{YES_OR_NO_Y} 
            where 

            pp.INVEST_YESORNO = 'Y' AND tpd.TRADE_STATUS =  #{TRADE_STATUS_01}

                and tpd.IS_CANCEL = #{YES_OR_NO_Y}  

                and tpd.BUSI_TYPE = #{COM_TYPE_TRD03}

                and tpd.PS in (#{PS_CR},#{PS_CC})



        ) temp
        order by temp.tradeDate DESC

