choose.when:
SELECT T1.TOTLE_TRADE_ID busiCode, T1.PORTFOLIO_ID, PP.PORTFOLIO_ID actPortfolioId, T1.CCY, T2.PORTFOLIO_NAME portfolioName, T1.FINPROD_TYPE2 finprodType2, T1.TRADE_DATE tradeDate, T1.VDATE, T1.MDATE, T3.THEORY_PRIN prinAmt, T1.SETTLE_DATE,
T3.THEORY_INT intAmt,
T3.THEORY_AMT theoryAmt,
T4.INT_RATE intRate,
T4.basis, T1.COUNTER_ID counterId, T1.TRADER trader, T1.TRADE_AMT tradeAmt, T1.FINPROD_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL ptpdt on ptpdt.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID and t1.BRANCH = t4.BRANCH LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
WHERE T1.BUSI_TYPE = #{COMMON_BUSINESS_TYPETRD11}
and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} and T1.TOTLE_TRADE_ID = #{busiCode}
and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_Y} and T1.TOTLE_TRADE_ID = #{pTradeId}
ORDER BY T1.TRADE_DATE DESC

mapper.select:
SELECT DISTINCT case when T1.TRADE_STATUS = #{TRADE_STATUS_CX} then T1.P_TRADE_ID ELSE T1.TOTLE_TRADE_ID END id, case when T1.TRADE_STATUS = #{TRADE_STATUS_CX} then T1.P_TRADE_ID ELSE T1.TOTLE_TRADE_ID END text ,T1.PORTFOLIO_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1
T1.FINPROD_TYPE2 = #{FINPROD_TYPE}
#{item}
and (instr(TOTLE_TRADE_ID, #{search}) > 0)
